public class ClockEntry
{
    public int EmployeeId { get; }
    public DateTime ClockIn { get; }
    public DateTime? ClockOut { get; private set; }

    public ClockEntry(int employeeId, DateTime clockIn)
    {
        EmployeeId = employeeId;
        ClockIn = clockIn;
    }

    public void ClockOutEmployee(DateTime clockOut)
    {
        if (ClockOut is not null)
        {
            throw new InvalidOperationException("The entry is already complete.");
        }

        if (clockOut < ClockIn)
        {
            throw new ArgumentOutOfRangeException(nameof(clockOut));
        }

        ClockOut = clockOut;
    }

    public TimeSpan GetDuration()
    {
        if (ClockOut is null)
        {
            throw new InvalidOperationException("The entry is still open.");
        }

        return ClockOut.Value - ClockIn;
    }
}
